const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const mod = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{ .name = "kvhttp", .root_module = mod });
    b.installArtifact(exe);

    const run = b.addRunArtifact(exe);
    run.step.dependOn(b.getInstallStep());
    if (b.args) |args| run.addArgs(args);
    b.step("run", "Run the server").dependOn(&run.step);

    const tests = b.addTest(.{ .root_module = mod });
    b.step("test", "Run unit tests").dependOn(&b.addRunArtifact(tests).step);
}

//! HTTP/1.1 wire protocol for one client connection.
//!
//! Framing (head buffering, Content-Length and chunked bodies) is delegated to
//! `std.http.Reader`; the request line and headers are parsed here so that any
//! method token is accepted and routed (unknown methods must yield 405, not a
//! protocol error).

const Connection = @This();

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;
const net = Io.net;
const Status = std.http.Status;

const Store = @import("Store.zig");
const handler = @import("handler.zig");

const log = std.log.scoped(.connection);

/// Largest accepted request body: 1 MiB values plus generous headroom.
pub const max_body_len = 8 * 1024 * 1024;
/// Largest accepted request head; also the size of the receive buffer.
const max_head_len = 16 * 1024;

store: *Store,
io: Io,
gpa: Allocator,
stream: net.Stream,

/// Serves requests on the connection until the client or protocol ends it,
/// then closes the stream.
pub fn serve(c: Connection) void {
    defer c.stream.close(c.io);

    var recv_buffer: [max_head_len]u8 = undefined;
    var send_buffer: [16 * 1024]u8 = undefined;
    var stream_reader = c.stream.reader(c.io, &recv_buffer);
    var stream_writer = c.stream.writer(c.io, &send_buffer);
    var http_reader: std.http.Reader = .{
        .in = &stream_reader.interface,
        .interface = undefined,
        .state = .ready,
        .max_head_len = recv_buffer.len,
    };
    var arena: std.heap.ArenaAllocator = .init(c.gpa);
    defer arena.deinit();

    while (true) {
        _ = arena.reset(.retain_capacity);
        const keep_alive = c.serveRequest(arena.allocator(), &http_reader, &stream_writer.interface) catch |err| {
            switch (err) {
                error.WriteFailed => log.debug("write failed: {t}", .{stream_writer.err.?}),
                error.ReadFailed => log.debug("read failed: {t}", .{stream_reader.err.?}),
                else => log.debug("connection error: {t}", .{err}),
            }
            return;
        };
        if (!keep_alive) return;
    }
}

const ServeError = Allocator.Error || Io.Writer.Error || error{ ReadFailed, HttpRequestTruncated };

/// Reads one request and writes its response. Returns whether the connection
/// may be reused for another request.
fn serveRequest(c: Connection, arena: Allocator, in: *std.http.Reader, out: *Io.Writer) ServeError!bool {
    in.state = .ready;
    const head_bytes = in.receiveHead() catch |err| switch (err) {
        error.HttpConnectionClosing => return false,
        error.HttpHeadersOversize => return sendError(out, .request_header_fields_too_large),
        error.HttpRequestTruncated, error.ReadFailed => |e| return e,
    };

    // The head lives in the receive buffer, which reading the body reuses.
    const head = Head.parse(head_bytes) catch return sendError(out, .bad_request);
    const method = try arena.dupe(u8, head.method);
    const path = try arena.dupe(u8, head.path);

    if (head.content_length) |len| {
        if (len > max_body_len) return sendError(out, .payload_too_large);
    }
    if (head.expect_continue) {
        try out.writeAll("HTTP/1.1 100 Continue\r\n\r\n");
        try out.flush();
    }

    var transfer_buffer: [4096]u8 = undefined;
    const body: []const u8 = if (head.chunked or head.content_length != null) body: {
        const reader = in.bodyReader(&transfer_buffer, if (head.chunked) .chunked else .none, head.content_length);
        break :body reader.allocRemaining(arena, .limited(max_body_len)) catch |err| switch (err) {
            error.StreamTooLong => return sendError(out, .payload_too_large),
            error.OutOfMemory => |e| return e,
            error.ReadFailed => {
                if (in.body_err != null) return sendError(out, .bad_request);
                return error.ReadFailed;
            },
        };
    } else "";

    const response = try handler.handle(c.store, c.io, arena, .{ .method = method, .path = path, .body = body });
    try writeResponse(out, response, std.mem.eql(u8, method, "HEAD"), head.keep_alive);
    return head.keep_alive;
}

/// Sends a bodiless error response and reports that the connection must close.
fn sendError(out: *Io.Writer, status: Status) Io.Writer.Error!bool {
    try writeResponse(out, .{ .status = status }, false, false);
    return false;
}

fn writeResponse(out: *Io.Writer, response: handler.Response, omit_body: bool, keep_alive: bool) Io.Writer.Error!void {
    const status = response.status;
    try out.print("HTTP/1.1 {d} {s}\r\n", .{ @intFromEnum(status), status.phrase() orelse "" });
    // 1xx and 204 responses must not carry a Content-Length (RFC 9110 §8.6).
    if (status != .no_content) try out.print("Content-Length: {d}\r\n", .{response.body.len});
    if (response.content_type) |value| try out.print("Content-Type: {s}\r\n", .{value});
    if (response.allow) |value| try out.print("Allow: {s}\r\n", .{value});
    if (!keep_alive) try out.writeAll("Connection: close\r\n");
    try out.writeAll("\r\n");
    if (!omit_body) try out.writeAll(response.body);
    try out.flush();
}

/// The parts of a request head this server acts on. Slices point into the
/// buffer passed to `parse`.
const Head = struct {
    method: []const u8,
    /// Request target with any query string removed.
    path: []const u8,
    content_length: ?u64 = null,
    chunked: bool = false,
    expect_continue: bool = false,
    keep_alive: bool,

    const ParseError = error{
        InvalidRequestLine,
        UnsupportedVersion,
        InvalidHeader,
        InvalidContentLength,
        UnsupportedTransferEncoding,
        UnsupportedExpectation,
    };

    fn parse(bytes: []const u8) ParseError!Head {
        var lines = std.mem.splitScalar(u8, bytes, '\n');
        const request_line = trimCr(lines.first());

        var parts = std.mem.splitScalar(u8, request_line, ' ');
        const method = parts.next() orelse return error.InvalidRequestLine;
        const target = parts.next() orelse return error.InvalidRequestLine;
        const version = parts.next() orelse return error.InvalidRequestLine;
        if (parts.next() != null or !isToken(method) or target.len == 0 or target[0] != '/')
            return error.InvalidRequestLine;

        const http11 = if (std.mem.eql(u8, version, "HTTP/1.1"))
            true
        else if (std.mem.eql(u8, version, "HTTP/1.0"))
            false
        else
            return error.UnsupportedVersion;

        var head: Head = .{
            .method = method,
            .path = target[0 .. std.mem.findScalar(u8, target, '?') orelse target.len],
            .keep_alive = http11,
        };

        while (lines.next()) |raw| {
            const line = trimCr(raw);
            if (line.len == 0) break;
            const colon = std.mem.findScalar(u8, line, ':') orelse return error.InvalidHeader;
            const name = line[0..colon];
            if (!isToken(name)) return error.InvalidHeader;
            const value = std.mem.trim(u8, line[colon + 1 ..], " \t");

            if (std.ascii.eqlIgnoreCase(name, "content-length")) {
                const len = std.fmt.parseUnsigned(u64, value, 10) catch return error.InvalidContentLength;
                if (head.content_length) |prev| if (prev != len) return error.InvalidContentLength;
                head.content_length = len;
            } else if (std.ascii.eqlIgnoreCase(name, "transfer-encoding")) {
                if (!std.ascii.eqlIgnoreCase(value, "chunked")) return error.UnsupportedTransferEncoding;
                head.chunked = true;
            } else if (std.ascii.eqlIgnoreCase(name, "connection")) {
                var tokens = std.mem.tokenizeAny(u8, value, ", \t");
                while (tokens.next()) |token| {
                    if (std.ascii.eqlIgnoreCase(token, "close")) head.keep_alive = false;
                    if (std.ascii.eqlIgnoreCase(token, "keep-alive")) head.keep_alive = true;
                }
            } else if (std.ascii.eqlIgnoreCase(name, "expect")) {
                if (!std.ascii.eqlIgnoreCase(value, "100-continue")) return error.UnsupportedExpectation;
                head.expect_continue = http11;
            }
        }

        // A message with both framings is a request-smuggling vector (RFC 9112 §6.1).
        if (head.chunked and head.content_length != null) return error.InvalidContentLength;
        return head;
    }

    fn trimCr(line: []const u8) []const u8 {
        return std.mem.trimEnd(u8, line, "\r");
    }

    fn isToken(s: []const u8) bool {
        if (s.len == 0) return false;
        for (s) |ch| switch (ch) {
            'A'...'Z', 'a'...'z', '0'...'9', '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~' => {},
            else => return false,
        };
        return true;
    }
};

test "Head.parse" {
    const head = try Head.parse("PUT /kv/a?x=1 HTTP/1.1\r\nHost: x\r\ncontent-length: 5\r\nConnection: close\r\n\r\n");
    try std.testing.expectEqualStrings("PUT", head.method);
    try std.testing.expectEqualStrings("/kv/a", head.path);
    try std.testing.expectEqual(5, head.content_length.?);
    try std.testing.expect(!head.keep_alive);

    const custom = try Head.parse("FROB /health HTTP/1.0\n\n");
    try std.testing.expectEqualStrings("FROB", custom.method);
    try std.testing.expect(!custom.keep_alive);

    try std.testing.expectError(error.InvalidRequestLine, Head.parse("GET\r\n\r\n"));
    try std.testing.expectError(error.UnsupportedVersion, Head.parse("GET / HTTP/2\r\n\r\n"));
    try std.testing.expectError(error.InvalidContentLength, Head.parse("GET / HTTP/1.1\r\nContent-Length: -1\r\n\r\n"));
}

//! Thread-safe in-memory key-value store.
//!
//! Keys and values are owned copies; readers receive their own copy of a value
//! so that concurrent replacement or deletion can never invalidate it.

const Store = @This();

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;

gpa: Allocator,
lock: Io.RwLock = .init,
map: std.StringHashMapUnmanaged([]u8) = .empty,

pub fn init(gpa: Allocator) Store {
    return .{ .gpa = gpa };
}

pub fn deinit(s: *Store) void {
    var it = s.map.iterator();
    while (it.next()) |entry| {
        s.gpa.free(entry.key_ptr.*);
        s.gpa.free(entry.value_ptr.*);
    }
    s.map.deinit(s.gpa);
    s.* = undefined;
}

/// Stores a copy of `value` under `key`. Returns true if the key was new.
pub fn put(s: *Store, io: Io, key: []const u8, value: []const u8) Allocator.Error!bool {
    const value_copy = try s.gpa.dupe(u8, value);
    errdefer s.gpa.free(value_copy);

    s.lock.lockUncancelable(io);
    defer s.lock.unlock(io);

    const gop = try s.map.getOrPut(s.gpa, key);
    if (gop.found_existing) {
        s.gpa.free(gop.value_ptr.*);
        gop.value_ptr.* = value_copy;
        return false;
    }
    gop.key_ptr.* = s.gpa.dupe(u8, key) catch |err| {
        s.map.removeByPtr(gop.key_ptr);
        return err;
    };
    gop.value_ptr.* = value_copy;
    return true;
}

/// Returns a copy of the value stored under `key`, allocated with `allocator`,
/// or null if the key is absent.
pub fn get(s: *Store, io: Io, allocator: Allocator, key: []const u8) Allocator.Error!?[]u8 {
    s.lock.lockSharedUncancelable(io);
    defer s.lock.unlockShared(io);

    const value = s.map.get(key) orelse return null;
    return try allocator.dupe(u8, value);
}

/// Removes `key`. Returns true if it was present.
pub fn delete(s: *Store, io: Io, key: []const u8) bool {
    s.lock.lockUncancelable(io);
    defer s.lock.unlock(io);

    const kv = s.map.fetchRemove(key) orelse return false;
    s.gpa.free(kv.key);
    s.gpa.free(kv.value);
    return true;
}

/// Returns a copy of every key, sorted ascending by byte order. The outer
/// slice and every key are allocated with `allocator`.
pub fn sortedKeys(s: *Store, io: Io, allocator: Allocator) Allocator.Error![][]u8 {
    const keys = blk: {
        s.lock.lockSharedUncancelable(io);
        defer s.lock.unlockShared(io);

        const keys = try allocator.alloc([]u8, s.map.count());
        var filled: usize = 0;
        errdefer {
            for (keys[0..filled]) |k| allocator.free(k);
            allocator.free(keys);
        }
        var it = s.map.keyIterator();
        while (it.next()) |k| : (filled += 1) keys[filled] = try allocator.dupe(u8, k.*);
        break :blk keys;
    };
    std.mem.sortUnstable([]u8, keys, {}, lessThan);
    return keys;
}

fn lessThan(_: void, a: []u8, b: []u8) bool {
    return std.mem.order(u8, a, b) == .lt;
}

test "put, get, replace, delete" {
    const io = std.testing.io;
    var arena: std.heap.ArenaAllocator = .init(std.testing.allocator);
    defer arena.deinit();
    var s: Store = .init(std.testing.allocator);
    defer s.deinit();

    try std.testing.expect(try s.put(io, "a", "hello"));
    try std.testing.expectEqualStrings("hello", (try s.get(io, arena.allocator(), "a")).?);
    try std.testing.expect(!try s.put(io, "a", "world"));
    try std.testing.expectEqualStrings("world", (try s.get(io, arena.allocator(), "a")).?);
    try std.testing.expect(s.delete(io, "a"));
    try std.testing.expectEqual(null, try s.get(io, arena.allocator(), "a"));
    try std.testing.expect(!s.delete(io, "a"));
}

test "sortedKeys" {
    const io = std.testing.io;
    var arena: std.heap.ArenaAllocator = .init(std.testing.allocator);
    defer arena.deinit();
    var s: Store = .init(std.testing.allocator);
    defer s.deinit();

    for ([_][]const u8{ "b", "a", "_", "C", "aa" }) |k| _ = try s.put(io, k, k);
    const keys = try s.sortedKeys(io, arena.allocator());
    try std.testing.expectEqual(5, keys.len);
    const want = [_][]const u8{ "C", "_", "a", "aa", "b" };
    for (want, keys) |w, k| try std.testing.expectEqualStrings(w, k);
}

//! Routing and request handling for the kvhttp API, independent of the wire
//! protocol.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;
const Status = std.http.Status;

const Store = @import("Store.zig");

pub const max_key_len = 64;

pub const Request = struct {
    method: []const u8,
    /// Request target without any query string.
    path: []const u8,
    body: []const u8 = "",
};

pub const Response = struct {
    status: Status,
    body: []const u8 = "",
    content_type: ?[]const u8 = null,
    /// Value of the `Allow` header for 405 responses.
    allow: ?[]const u8 = null,

    fn methodNotAllowed(allow: []const u8) Response {
        return .{ .status = .method_not_allowed, .allow = allow };
    }
};

/// Handles one request. Response bodies are allocated with `arena`, which the
/// caller frees once the response has been sent.
pub fn handle(store: *Store, io: Io, arena: Allocator, req: Request) Allocator.Error!Response {
    if (std.mem.eql(u8, req.path, "/health")) {
        if (!isMethod(req, "GET")) return .methodNotAllowed("GET");
        return .{ .status = .ok, .body = "ok", .content_type = "text/plain; charset=utf-8" };
    }

    if (std.mem.eql(u8, req.path, "/kv")) {
        if (!isMethod(req, "GET")) return .methodNotAllowed("GET");
        const keys = try store.sortedKeys(io, arena);
        const json = try std.json.Stringify.valueAlloc(arena, keys, .{});
        return .{ .status = .ok, .body = json, .content_type = "application/json" };
    }

    if (std.mem.startsWith(u8, req.path, "/kv/")) {
        const key = req.path["/kv/".len..];
        if (!isValidKey(key)) return .{ .status = .bad_request };

        if (isMethod(req, "GET")) {
            const value = try store.get(io, arena, key) orelse return .{ .status = .not_found };
            return .{ .status = .ok, .body = value, .content_type = "application/octet-stream" };
        }
        if (isMethod(req, "PUT")) {
            const created = try store.put(io, key, req.body);
            return .{ .status = if (created) .created else .ok };
        }
        if (isMethod(req, "DELETE")) {
            return .{ .status = if (store.delete(io, key)) .no_content else .not_found };
        }
        return .methodNotAllowed("GET, PUT, DELETE");
    }

    return .{ .status = .not_found };
}

fn isMethod(req: Request, method: []const u8) bool {
    return std.mem.eql(u8, req.method, method);
}

/// A key matches `[A-Za-z0-9_-]{1,64}`.
pub fn isValidKey(key: []const u8) bool {
    if (key.len == 0 or key.len > max_key_len) return false;
    for (key) |c| switch (c) {
        'A'...'Z', 'a'...'z', '0'...'9', '_', '-' => {},
        else => return false,
    };
    return true;
}

const testing = std.testing;

const Harness = struct {
    arena: std.heap.ArenaAllocator,
    store: Store,

    fn init() Harness {
        return .{ .arena = .init(testing.allocator), .store = .init(testing.allocator) };
    }

    fn deinit(h: *Harness) void {
        h.store.deinit();
        h.arena.deinit();
    }

    fn do(h: *Harness, method: []const u8, path: []const u8, body: []const u8) !Response {
        return handle(&h.store, testing.io, h.arena.allocator(), .{ .method = method, .path = path, .body = body });
    }

    fn status(h: *Harness, method: []const u8, path: []const u8) !Status {
        return (try h.do(method, path, "")).status;
    }
};

test "crud" {
    var h: Harness = .init();
    defer h.deinit();

    try testing.expectEqual(.created, (try h.do("PUT", "/kv/a", "hello")).status);
    try testing.expectEqualStrings("hello", (try h.do("GET", "/kv/a", "")).body);
    try testing.expectEqual(.ok, (try h.do("PUT", "/kv/a", "world")).status);
    try testing.expectEqualStrings("world", (try h.do("GET", "/kv/a", "")).body);
    try testing.expectEqual(.no_content, try h.status("DELETE", "/kv/a"));
    try testing.expectEqual(.not_found, try h.status("GET", "/kv/a"));
    try testing.expectEqual(.not_found, try h.status("DELETE", "/kv/a"));
}

test "listing" {
    var h: Harness = .init();
    defer h.deinit();

    try testing.expectEqualStrings("[]", (try h.do("GET", "/kv", "")).body);
    for ([_][]const u8{ "/kv/b", "/kv/a", "/kv/c" }) |p| _ = try h.do("PUT", p, "x");
    const resp = try h.do("GET", "/kv", "");
    try testing.expectEqual(.ok, resp.status);
    try testing.expectEqualStrings("application/json", resp.content_type.?);
    try testing.expectEqualStrings("[\"a\",\"b\",\"c\"]", resp.body);
}

test "errors" {
    var h: Harness = .init();
    defer h.deinit();

    const long = "/kv/" ++ "a" ** 65;
    for ([_][]const u8{ "/kv/", "/kv/a/b", "/kv/bad.key", long }) |p|
        try testing.expectEqual(.bad_request, try h.status("GET", p));
    try testing.expectEqual(.bad_request, try h.status("PATCH", "/kv/bad.key"));
    for ([_][]const u8{ "/", "/nope", "/health/", "/kvx" }) |p|
        try testing.expectEqual(.not_found, try h.status("GET", p));
    try testing.expectEqual(.method_not_allowed, try h.status("POST", "/health"));
    try testing.expectEqual(.method_not_allowed, try h.status("PUT", "/kv"));
    try testing.expectEqual(.method_not_allowed, try h.status("PATCH", "/kv/a"));
    try testing.expectEqual(.method_not_allowed, try h.status("HEAD", "/kv/a"));
    try testing.expectEqual(.created, try h.status("PUT", "/kv/" ++ "a" ** 64));
}

//! kvhttp: an in-memory key-value store served over HTTP/1.1.
//!
//! Usage: `app <port>` listens on 127.0.0.1:<port> until killed.

const std = @import("std");
const Io = std.Io;
const net = Io.net;

const Store = @import("Store.zig");
const Connection = @import("Connection.zig");

const log = std.log.scoped(.kvhttp);

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    const gpa = init.gpa;

    const args = try init.minimal.args.toSlice(init.arena.allocator());
    const port = parsePort(args) orelse {
        std.log.err("usage: app <port>", .{});
        std.process.exit(2);
    };

    var store: Store = .init(gpa);
    defer store.deinit();

    const address: net.IpAddress = .{ .ip4 = .loopback(port) };
    var server = try address.listen(io, .{ .reuse_address = true, .kernel_backlog = 1024 });
    defer server.deinit(io);
    log.info("listening on 127.0.0.1:{d}", .{port});

    var connections: Io.Group = .init;
    defer connections.cancel(io);

    while (true) {
        const stream = server.accept(io) catch |err| switch (err) {
            error.Canceled => |e| return e,
            else => {
                log.warn("accept failed: {t}", .{err});
                continue;
            },
        };
        const connection: Connection = .{ .store = &store, .io = io, .gpa = gpa, .stream = stream };
        connections.concurrent(io, Connection.serve, .{connection}) catch |err| {
            log.warn("cannot serve connection: {t}", .{err});
            stream.close(io);
        };
    }
}

fn parsePort(args: []const [:0]const u8) ?u16 {
    if (args.len != 2) return null;
    const port = std.fmt.parseUnsigned(u16, args[1], 10) catch return null;
    return if (port == 0) null else port;
}

test {
    std.testing.refAllDecls(@This());
    _ = Store;
    _ = Connection;
    _ = @import("handler.zig");
}
